static uint32_t z_t913_entries_cap(uint32_t _capacity) {
    return (uint32_t)((((uint64_t)_capacity) * 2u) / 3u);
}

static void z_t913_destroy(z_t913_t* p);
static void z_t913_destroy(z_t913_t* p) {
    if (!p) return;
    for (uint32_t i = 0; i < p->length; i++) {
        z_t875_destroy(&p->entries[i].value);
    }
    free(p->indices);
    free(p->entries);
    /* NO free(p) -- the struct is on the stack */
}

